}

fn print(x: Int) {
    let s = int_to_str(x)
    print_str(s)
}

fn int_to_str(n: Int) -> Str {
    let mut digits = vec()
    let mut n_copy = n
    while n_copy > 0 {
        digits.push(n_copy % 10)
        n_copy = trunc(n_copy / 10)
    }
    let mut s = str()
    for digit in &digits {
        s = concat(s, int_to_str(digit))
    }
    s
}

fn print_str(s: Str) {
    for c in chars(s) {
        print(c)
    }
    print(Unit)
}

fn chars(s: Str) -> Vec<Str> {
    let mut chars = vec()
    let mut s_copy = s
    while len(s_copy) > 0 {
        let c = get(s_copy, 0)
        chars.push(c)
        s_copy = drop_first(s_copy)
    }
    chars
}

