    let mut digits = vec()
    let mut x = n
    while x != 0 {
        digits = push(digits, x % 10)
        x = trunc(x / 10)
    }
    let mut s = str()
    for d in &digits {
        s = concat(s, int_to_str(d))
    }
    return s
}

