fn min(a: Int, b: Int, c: Int, d: Int) -> Int {
    if a < b {
        if a < c {
            if a < d {
                a
            } else {
                d
            }
        } else {
            if c < d {
                c
            } else {
                d
            }
        }
    } else {
        if b < c {
            if b < d {
                b
            } else {
                d
            }
        } else {
            if c < d {
                c
            } else {
                d
            }
        }
    }
}

fn max(a: Int, b: Int, c: Int, d: Int) -> Int {
    if a > b {
        if a > c {
            if a > d {
                a
            } else {
                d
            }
        } else {
            if c > d {
                c
            } else {
                d
            }
        }
    } else {
        if b > c {
            if b > d {
                b
            } else {
                d
            }
        } else {
            if c > d {
                c
            } else {
                d
            }
        }
    }
}

