fn chars(s: Str) -> Vec<Str> {
    let mut result = vec()
    for i in 0 < s.len() {
        result.push(get(s, i)?)
    }
    result
}

fn get(s: Str, i: Int) -> Option<Str> {
    if i >= s.len() {
        None
    } else {
        Some(s.chars().nth(i).unwrap())
    }
}

