fn area(a: Int, b: Int) -> Int {
    a * b
}

fn perimeter(a: Int, b: Int) -> Int {
    2 * (a + b)
}

fn main() {
    let a = 9
    let b = 3
    print(area(a, b))
    print(perimeter(a, b))
}

fn area(w: Int, h: Int) -> Int {
    w * h
}

fn perimeter(w: Int, h: Int) -> Int {
    2 * (w + h)
}

fn main() {
    let width = 9
    let height = 3
    print(area(width, height))
    print(perimeter(width, height))
}

